package android.graphics;
public class Typeface {public static final int BOLD=1;public static Typeface MONOSPACE=new Typeface("Monospaced",0);final String family;final int style;java.awt.Font awt;Typeface(String family,int style){this.family=family;this.style=style;awt=new java.awt.Font(family,style,12);}public static Typeface create(String family,int style){return new Typeface(family.equals("sans-serif-condensed")?"DejaVu Sans Condensed":family,style);}public static Typeface createFromAsset(android.content.res.AssetManager a,String path){try(java.io.InputStream in=a.open(path)){Typeface t=new Typeface("Digital-7",0);t.awt=java.awt.Font.createFont(java.awt.Font.TRUETYPE_FONT,in);return t;}catch(Exception e){throw new RuntimeException(e);}}}
